/**
 * Knowledge Graph API client — BATCH-25/TASK-02
 *
 * Provides typed functions for the knowledge graph endpoints:
 *   GET /knowledge-graph/stats
 *   GET /knowledge-graph/entities?type=...&search=...&limit=100
 *   GET /knowledge-graph/entity/{id}
 *   GET /knowledge-graph/subgraph/{id}?depth=2
 */

import { apiFetch } from "./client";

// ── Types ─────────────────────────────────────────────────────────

export interface GraphStats {
  entity_count: number;
  relationship_count: number;
  entity_types: Record<string, number>;
  relation_types: Record<string, number>;
}

export interface TruthInfo {
  confidence: number;
  frequency: number;
  source_count: number;
}

export interface GraphEntity {
  id: string;
  entity_type: string;
  name: string;
  aliases: string[];
  properties: Record<string, unknown>;
  truth: TruthInfo;
}

export interface GraphRelationship {
  source_id: string;
  target_id: string;
  relation_type: string;
  weight: number;
  evidence: string[];
  truth: TruthInfo;
}

export interface EntityDetail {
  entity: GraphEntity;
  relationships: GraphRelationship[];
}

export interface Subgraph {
  entities: GraphEntity[];
  relationships: GraphRelationship[];
}

// ── API Functions ─────────────────────────────────────────────────

/** GET /knowledge-graph/stats → graph statistics */
export function getGraphStats(): Promise<GraphStats> {
  return apiFetch<GraphStats>("/knowledge-graph/stats");
}

/** GET /knowledge-graph/entities → entity list with optional filters (HB-02: max 100) */
export function getEntities(params?: {
  type?: string;
  search?: string;
  limit?: number;
}): Promise<GraphEntity[]> {
  const query = new URLSearchParams();
  if (params?.type) query.set("type", params.type);
  if (params?.search) query.set("search", params.search);
  if (params?.limit) query.set("limit", String(params.limit));
  const qs = query.toString();
  return apiFetch<GraphEntity[]>(`/knowledge-graph/entities${qs ? `?${qs}` : ""}`);
}

/** GET /knowledge-graph/entity/{id} → entity with relationships */
export function getEntity(id: string): Promise<EntityDetail> {
  return apiFetch<EntityDetail>(`/knowledge-graph/entity/${encodeURIComponent(id)}`);
}

/** GET /knowledge-graph/subgraph/{id}?depth=N → connected subgraph */
export function getSubgraph(id: string, depth = 2): Promise<Subgraph> {
  return apiFetch<Subgraph>(
    `/knowledge-graph/subgraph/${encodeURIComponent(id)}?depth=${depth}`,
  );
}

import { describe, it, expect, beforeEach, vi } from "vitest";
import { getGraphStats, getEntities, getEntity, getSubgraph } from "@/api/knowledge-graph";
import type {
  GraphStats,
  GraphEntity,
  EntityDetail,
  Subgraph,
} from "@/api/knowledge-graph";
import { apiFetch } from "@/api/client";

vi.mock("@/api/client", () => ({
  apiFetch: vi.fn(),
}));

const mockApiFetch = vi.mocked(apiFetch);

describe("BATCH-25/TASK-02: Knowledge Graph API Client", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  // ── TEST-25-02-01: getGraphStats() calls correct endpoint ──────
  it("TEST-25-02-01: getGraphStats() correct endpoint", async () => {
    const expected: GraphStats = {
      entity_count: 42,
      relationship_count: 78,
      entity_types: { paper: 20, author: 15, concept: 7 },
      relation_types: { cites: 50, uses_method: 28 },
    };
    mockApiFetch.mockResolvedValueOnce(expected);

    const result = await getGraphStats();

    expect(mockApiFetch).toHaveBeenCalledWith("/knowledge-graph/stats");
    expect(result).toEqual(expected);
    expect(result.entity_count).toBe(42);
    expect(result.relationship_count).toBe(78);
  });

  // ── TEST-25-02-02: getEntities() accepts type/search params ────
  it("TEST-25-02-02: getEntities() accepts type/search params", async () => {
    const entities: GraphEntity[] = [
      {
        id: "paper:1",
        entity_type: "paper",
        name: "Attention Is All You Need",
        aliases: ["Transformer"],
        properties: {},
        truth: { confidence: 0.9, frequency: 0.8, source_count: 5 },
      },
    ];
    mockApiFetch.mockResolvedValueOnce(entities);

    const result = await getEntities({ type: "paper", search: "attention" });

    expect(mockApiFetch).toHaveBeenCalledWith(
      expect.stringContaining("/knowledge-graph/entities"),
    );
    expect(mockApiFetch).toHaveBeenCalledWith(
      expect.stringContaining("type=paper"),
    );
    expect(mockApiFetch).toHaveBeenCalledWith(
      expect.stringContaining("search=attention"),
    );
    expect(result).toEqual(entities);
    expect(result[0].name).toBe("Attention Is All You Need");
  });

  // ── TEST-25-02-03: getEntity(id) calls correct endpoint ────────
  it("TEST-25-02-03: getEntity(id) correct endpoint", async () => {
    const detail: EntityDetail = {
      entity: {
        id: "concept:transformer",
        entity_type: "concept",
        name: "Transformer",
        aliases: [],
        properties: {},
        truth: { confidence: 0.95, frequency: 0.9, source_count: 10 },
      },
      relationships: [
        {
          source_id: "paper:1",
          target_id: "concept:transformer",
          relation_type: "proposes_method",
          weight: 1.5,
          evidence: [],
          truth: { confidence: 0.8, frequency: 0.7, source_count: 3 },
        },
      ],
    };
    mockApiFetch.mockResolvedValueOnce(detail);

    const result = await getEntity("concept:transformer");

    expect(mockApiFetch).toHaveBeenCalledWith(
      "/knowledge-graph/entity/concept%3Atransformer",
    );
    expect(result).toEqual(detail);
    expect(result.entity.name).toBe("Transformer");
    expect(result.relationships).toHaveLength(1);
  });

  // ── TEST-25-02-04: getSubgraph(id, depth) calls correct endpoint ─
  it("TEST-25-02-04: getSubgraph(id, depth) correct endpoint", async () => {
    const subgraph: Subgraph = {
      entities: [
        {
          id: "concept:1",
          entity_type: "concept",
          name: "Alpha",
          aliases: [],
          properties: {},
          truth: { confidence: 0.8, frequency: 0.7, source_count: 2 },
        },
        {
          id: "paper:1",
          entity_type: "paper",
          name: "Paper One",
          aliases: [],
          properties: {},
          truth: { confidence: 0.9, frequency: 0.8, source_count: 4 },
        },
      ],
      relationships: [
        {
          source_id: "paper:1",
          target_id: "concept:1",
          relation_type: "uses_method",
          weight: 1.0,
          evidence: [],
          truth: { confidence: 0.7, frequency: 0.6, source_count: 1 },
        },
      ],
    };
    mockApiFetch.mockResolvedValueOnce(subgraph);

    const result = await getSubgraph("concept:1", 3);

    expect(mockApiFetch).toHaveBeenCalledWith(
      "/knowledge-graph/subgraph/concept%3A1?depth=3",
    );
    expect(result).toEqual(subgraph);
    expect(result.entities).toHaveLength(2);
    expect(result.relationships).toHaveLength(1);
  });
});

