/**
 * GraphCanvas — SVG-based knowledge graph visualization (HB-01: client-side only).
 *
 * Renders entities as colored circles and relationships as lines.
 * No D3 dependency — pure SVG with React state for positioning.
 */

import { useCallback, useMemo, useRef, useState } from "react";
import type { GraphEntity, GraphRelationship } from "@/api/knowledge-graph";

// ── Color map for entity types ────────────────────────────────────

const TYPE_COLORS: Record<string, string> = {
  paper: "#3b82f6",
  author: "#10b981",
  method: "#f59e0b",
  dataset: "#8b5cf6",
  concept: "#ef4444",
};

const DEFAULT_COLOR = "#6b7280";
const NODE_RADIUS = 20;

interface LayoutNode {
  id: string;
  x: number;
  y: number;
  entity: GraphEntity;
}

// ── Simple force-directed-like layout (deterministic placement) ───

function layoutNodes(entities: GraphEntity[], width: number, height: number): LayoutNode[] {
  const cx = width / 2;
  const cy = height / 2;

  return entities.map((entity, i) => {
    const angle = (2 * Math.PI * i) / Math.max(entities.length, 1);
    const radius = Math.min(width, height) * 0.35;
    return {
      id: entity.id,
      x: cx + radius * Math.cos(angle),
      y: cy + radius * Math.sin(angle),
      entity,
    };
  });
}

interface GraphCanvasProps {
  entities: GraphEntity[];
  relationships: GraphRelationship[];
  selectedId: string | null;
  onSelectEntity: (id: string) => void;
  className?: string;
}

export function GraphCanvas({
  entities,
  relationships,
  selectedId,
  onSelectEntity,
  className,
}: GraphCanvasProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [dimensions, setDimensions] = useState({ width: 800, height: 500 });
  const [dragOffset, setDragOffset] = useState<{ x: number; y: number } | null>(null);
  const [dragNodeId, setDragNodeId] = useState<string | null>(null);

  const nodes = useMemo(
    () => layoutNodes(entities, dimensions.width, dimensions.height),
    [entities, dimensions.width, dimensions.height],
  );

  const nodeMap = useMemo(() => {
    const m = new Map<string, LayoutNode>();
    nodes.forEach((n) => m.set(n.id, n));
    return m;
  }, [nodes]);

  const handleResize = useCallback(() => {
    if (containerRef.current) {
      const { clientWidth, clientHeight } = containerRef.current;
      setDimensions({ width: clientWidth || 800, height: clientHeight || 500 });
    }
  }, []);

  // Mouse handlers for drag
  const handleMouseDown = useCallback(
    (e: React.MouseEvent, nodeId: string) => {
      e.stopPropagation();
      const node = nodeMap.get(nodeId);
      if (node) {
        setDragNodeId(nodeId);
        setDragOffset({ x: e.clientX - node.x, y: e.clientY - node.y });
      }
    },
    [nodeMap],
  );

  const handleMouseUp = useCallback(() => {
    setDragNodeId(null);
    setDragOffset(null);
  }, []);

  return (
    <div
      ref={containerRef}
      className={`relative border rounded-lg bg-background overflow-hidden ${className || ""}`}
      style={{ minHeight: 400 }}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${dimensions.width} ${dimensions.height}`}
        className="select-none"
      >
        {/* Edges */}
        {relationships.map((rel, i) => {
          const source = nodeMap.get(rel.source_id);
          const target = nodeMap.get(rel.target_id);
          if (!source || !target) return null;

          return (
            <line
              key={`edge-${i}`}
              x1={source.x}
              y1={source.y}
              x2={target.x}
              y2={target.y}
              stroke={selectedId === rel.source_id || selectedId === rel.target_id ? "#3b82f6" : "#94a3b8"}
              strokeWidth={selectedId === rel.source_id || selectedId === rel.target_id ? 2 : 1}
              opacity={0.6}
            />
          );
        })}

        {/* Nodes */}
        {nodes.map((node) => {
          const color = TYPE_COLORS[node.entity.entity_type] || DEFAULT_COLOR;
          const isSelected = node.id === selectedId;

          return (
            <g
              key={node.id}
              transform={`translate(${node.x}, ${node.y})`}
              className="cursor-pointer"
              onClick={() => onSelectEntity(node.id)}
              onMouseDown={(e) => handleMouseDown(e, node.id)}
            >
              {/* Selection ring */}
              {isSelected && (
                <circle r={NODE_RADIUS + 4} fill="none" stroke="#3b82f6" strokeWidth={2} />
              )}
              <circle
                r={NODE_RADIUS}
                fill={color}
                opacity={0.85}
                className="transition-all duration-150 hover:opacity-100"
              />
              {/* Label */}
              <text
                textAnchor="middle"
                y={NODE_RADIUS + 14}
                className="text-xs fill-muted-foreground"
                fontSize={10}
              >
                {node.entity.name.length > 18
                  ? node.entity.name.slice(0, 16) + "…"
                  : node.entity.name}
              </text>
              {/* Type badge */}
              <text
                textAnchor="middle"
                y={4}
                className="text-white text-[8px] font-bold pointer-events-none"
                fill="white"
                fontSize={8}
              >
                {node.entity.entity_type.slice(0, 3).toUpperCase()}
              </text>
            </g>
          );
        })}
      </svg>

      {/* Legend */}
      <div className="absolute bottom-2 left-2 flex gap-3 bg-background/80 backdrop-blur-sm rounded-md px-2 py-1 text-xs text-muted-foreground">
        {Object.entries(TYPE_COLORS).map(([type, color]) => (
          <span key={type} className="flex items-center gap-1">
            <span className="inline-block w-2 h-2 rounded-full" style={{ backgroundColor: color }} />
            {type}
          </span>
        ))}
      </div>
    </div>
  );
}

/**
 * EntityDetail — detail panel for a selected knowledge graph entity.
 *
 * Shows entity properties, truth info, and connected relationships.
 */

import type { EntityDetail as EntityDetailType } from "@/api/knowledge-graph";
import { X, ExternalLink } from "lucide-react";

interface EntityDetailProps {
  detail: EntityDetailType;
  onClose: () => void;
  onNavigateToEntity?: (id: string) => void;
}

const TYPE_COLORS: Record<string, string> = {
  paper: "bg-blue-100 text-blue-800",
  author: "bg-emerald-100 text-emerald-800",
  method: "bg-amber-100 text-amber-800",
  dataset: "bg-purple-100 text-purple-800",
  concept: "bg-red-100 text-red-800",
};

export function EntityDetail({ detail, onClose, onNavigateToEntity }: EntityDetailProps) {
  const { entity, relationships } = detail;

  return (
    <div className="border rounded-lg bg-card p-4 space-y-4">
      {/* Header */}
      <div className="flex items-start justify-between">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span
              className={`inline-block px-2 py-0.5 rounded-full text-xs font-medium ${
                TYPE_COLORS[entity.entity_type] || "bg-gray-100 text-gray-800"
              }`}
            >
              {entity.entity_type}
            </span>
          </div>
          <h3 className="text-lg font-semibold leading-tight">{entity.name}</h3>
          {entity.aliases.length > 0 && (
            <p className="text-sm text-muted-foreground mt-1">
              Also known as: {entity.aliases.join(", ")}
            </p>
          )}
        </div>
        <button
          onClick={onClose}
          className="p-1 rounded-md hover:bg-accent text-muted-foreground"
          aria-label="Close detail panel"
        >
          <X className="h-4 w-4" />
        </button>
      </div>

      {/* Truth */}
      <div className="space-y-1">
        <h4 className="text-sm font-medium text-muted-foreground">Truth Value</h4>
        <div className="flex gap-4 text-sm">
          <span>
            Confidence: <strong>{(entity.truth.confidence * 100).toFixed(0)}%</strong>
          </span>
          <span>
            Frequency: <strong>{(entity.truth.frequency * 100).toFixed(0)}%</strong>
          </span>
          <span>
            Sources: <strong>{entity.truth.source_count}</strong>
          </span>
        </div>
        {/* Confidence bar */}
        <div className="w-full h-1.5 bg-muted rounded-full overflow-hidden">
          <div
            className="h-full bg-primary rounded-full"
            style={{ width: `${entity.truth.confidence * 100}%` }}
          />
        </div>
      </div>

      {/* Properties */}
      {Object.keys(entity.properties).length > 0 && (
        <div className="space-y-1">
          <h4 className="text-sm font-medium text-muted-foreground">Properties</h4>
          <div className="text-sm space-y-0.5">
            {Object.entries(entity.properties).map(([key, value]) => (
              <div key={key}>
                <span className="text-muted-foreground">{key}:</span>{" "}
                <span>{String(value)}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Relationships */}
      <div className="space-y-1">
        <h4 className="text-sm font-medium text-muted-foreground">
          Relationships ({relationships.length})
        </h4>
        {relationships.length === 0 ? (
          <p className="text-sm text-muted-foreground">No relationships found.</p>
        ) : (
          <div className="space-y-1 max-h-48 overflow-y-auto">
            {relationships.map((rel, i) => {
              const isSource = rel.source_id === entity.id;
              const otherId = isSource ? rel.target_id : rel.source_id;
              return (
                <div
                  key={i}
                  className="flex items-center gap-2 text-sm py-1 px-2 rounded hover:bg-accent cursor-pointer"
                  onClick={() => onNavigateToEntity?.(otherId)}
                >
                  <ExternalLink className="h-3 w-3 text-muted-foreground flex-shrink-0" />
                  <span className="text-muted-foreground">
                    {isSource ? "→" : "←"} {rel.relation_type}
                  </span>
                  <span className="font-mono text-xs">{otherId}</span>
                  <span className="ml-auto text-xs text-muted-foreground">
                    w={rel.weight.toFixed(1)}
                  </span>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

import { describe, it, expect, vi } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import { GraphCanvas } from "@/components/knowledge-graph/graph-canvas";
import { EntityDetail } from "@/components/knowledge-graph/entity-detail";
import type { GraphEntity, GraphRelationship, EntityDetail as EntityDetailType } from "@/api/knowledge-graph";

const sampleEntity: GraphEntity = {
  id: "concept:1",
  entity_type: "concept",
  name: "Transformer Architecture",
  aliases: ["Transformer"],
  properties: {},
  truth: { confidence: 0.9, frequency: 0.85, source_count: 10 },
};

const sampleEntity2: GraphEntity = {
  id: "paper:1",
  entity_type: "paper",
  name: "Attention Is All You Need",
  aliases: [],
  properties: { year: "2017" },
  truth: { confidence: 0.95, frequency: 0.9, source_count: 15 },
};

const sampleRel: GraphRelationship = {
  source_id: "paper:1",
  target_id: "concept:1",
  relation_type: "proposes_method",
  weight: 1.5,
  evidence: [],
  truth: { confidence: 0.8, frequency: 0.7, source_count: 3 },
};

const sampleDetail: EntityDetailType = {
  entity: sampleEntity,
  relationships: [sampleRel],
};

describe("BATCH-25/TASK-03: Graph Canvas and Entity Detail", () => {
  // ── TEST-25-03-01: GraphCanvas renders with entities ──────────
  it("TEST-25-03-01: GraphCanvas renders with entities", () => {
    const { container } = render(
      <GraphCanvas
        entities={[sampleEntity, sampleEntity2]}
        relationships={[sampleRel]}
        selectedId={null}
        onSelectEntity={vi.fn()}
      />,
    );

    // Should render SVG
    const svg = container.querySelector("svg");
    expect(svg).toBeTruthy();

    // Should render node circles (2 entities)
    const circles = container.querySelectorAll("circle");
    expect(circles.length).toBeGreaterThanOrEqual(2);

    // Should render entity names as text
    expect(screen.getByText("Transformer Architecture")).toBeTruthy();
    expect(screen.getByText("Attention Is All You Need")).toBeTruthy();

    // Legend should show types
    expect(screen.getByText("paper")).toBeTruthy();
    expect(screen.getByText("concept")).toBeTruthy();
  });

  // ── TEST-25-03-02: Entity click shows detail panel ────────────
  it("TEST-25-03-02: Entity click shows detail panel", () => {
    render(
      <EntityDetail
        detail={sampleDetail}
        onClose={vi.fn()}
      />,
    );

    // Entity name should be shown
    expect(screen.getByText("Transformer Architecture")).toBeTruthy();

    // Type badge
    expect(screen.getByText("concept")).toBeTruthy();

    // Truth values
    expect(screen.getByText(/90%/)).toBeTruthy();

    // Relationship should be listed
    expect(screen.getByText("proposes_method")).toBeTruthy();
  });

  // ── TEST-25-03-03: Type filter updates visible entities ────────
  it("TEST-25-03-03: Type filter updates visible entities", () => {
    const onSelect = vi.fn();

    // Render with only concept entities (simulating a filtered list)
    const { container, rerender } = render(
      <GraphCanvas
        entities={[sampleEntity]}
        relationships={[]}
        selectedId={null}
        onSelectEntity={onSelect}
      />,
    );

    // Only one entity should be rendered
    let labels = container.querySelectorAll("svg text");
    let hasTransformer = Array.from(labels).some(
      (t) => t.textContent?.includes("Transformer"),
    );
    expect(hasTransformer).toBe(true);

    // Rerender with different filtered entities
    rerender(
      <GraphCanvas
        entities={[sampleEntity2]}
        relationships={[]}
        selectedId={null}
        onSelectEntity={onSelect}
      />,
    );

    labels = container.querySelectorAll("svg text");
    const hasAttention = Array.from(labels).some(
      (t) => t.textContent?.includes("Attention"),
    );
    expect(hasAttention).toBe(true);
  });
});

